/**
 * @file check_lvl.c
 * @brief Verification-only "place level" data flow for expression bytes.
 *
 * Everything in this file is instrumentation: it reads the checked tree and prints
 * disagreements under `EXTC_DBG_LVL`, and it is not entered at all when that variable is
 * unset. No diagnostic and no generated byte depends on it.
 *
 * The question it answers is the one the per-site plan bit (`planZoneLevel`) answers
 * today, but derived from the whole body instead of from the statement that happens to be
 * walked: *at what level does this value's storage live?* A level is the depth of the
 * place that owns the bytes: `0` means the storage outlives the frame (a global, the
 * caller's home arena), `1` is the function body, larger numbers are deeper blocks, and a
 * `while` or `for` body is one deeper than the block around it. Smaller therefore means
 * longer lived.
 *
 * The lattice per value is
 *
 *     LVL_UNKNOWN (top)   no usable answer: reject at every store
 *     LVL_NONE    (bottom) the value owns no place bytes: i64, f64, bool, a literal
 *     0 .. 64             a known place level, 0 = beyond the frame
 *
 * and the join of two values that reach the same binding from two paths is their
 * **maximum**. The acceptance test is `argLvl <= placeLvl`, so a value that may arrive
 * from either arm of an `if` has to be judged by the *shorter*-lived arm: the store must
 * be safe for every possible value, and that is exactly what `max` computes. (`min` would
 * be right for a *destination*, where the requirement has to hold for the longest-lived
 * of several places the callee may store into; `checkCallRefArgs` already applies that
 * min when it derives `h`, and this file only reads the result.)
 *
 * Every value carries a second bit, `movable`: "the bytes are produced by an allocation
 * site inside this expression, so the site can be lowered to the destination's level"
 * (rule S1 of the pool-level design: a fresh site is lowered to the destination's level
 * instead of being rejected). A movable value is accepted even when its
 * lexical level is deeper than the place, which is what makes a direct `new`/`pool(...)`
 * argument agree with the checker instead of showing up as a false rejection. The join of
 * `movable` is `&&`: a value produced by either arm is movable only if both arms are.
 *
 * What is deliberately *not* modelled, and how the answer stays conservative:
 *
 *  - a parameter's bytes come from the caller, so its fact is `LVL_UNKNOWN` (top);
 *  - a `let`/`var` binding is one fact for the whole body (no per-point facts), so a
 *    value that is stored deep and then read back shallow reads at its fixed point;
 *  - only a callee whose summary already says `makesPool` gives its call a level;
 *    `calleeMakesPool` is a closure that is still settling while bodies are being checked,
 *    so a transitive case reads as "no" and falls back to `LVL_UNKNOWN` (more rejections,
 *    never fewer);
 *  - the pool primitives (`poolSlice`, `poolResize`, ...) are views into the pool's own
 *    plate, so they are `LVL_UNKNOWN` rather than "fresh".
 *
 * The walk mirrors `src/check/check_dataflow.c`: the structured statement tree *is* the
 * fixed point (sequence, both arms of an `if` joined, loops iterated), every transfer only
 * moves a fact upward in the lattice, and the iteration is capped by the same round limit
 * the reference-depth DFA uses.
 */
#include "check_internal.h"
#include "plan.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/** Maximum number of tracked bindings in one function body. */
#define LVL_MAX_VARS 256
/** Maximum number of tracked fields per binding. */
#define LVL_MAX_FIELDS 4
/** Round limit for a loop; the same bound as `DFA_ROUNDS`. */
#define LVL_ROUNDS 64
/** Nesting limit for the recursive walk; the same bound as `DFA_MAX_NEST`. */
#define LVL_MAX_NEST 256
/** Safety cap on printed disagreement lines for one compiler run. */
#define LVL_MAX_PRINT 20000

/** Bottom: the value owns no place bytes and fits in any place. */
#define LVL_NONE (-2)
/** Top: no usable answer, so every store is rejected. */
#define LVL_UNKNOWN 100000

/** One tracked field of a binding. */
typedef struct {
    const char *name;   /**< Field name as written at the store. */
    int         lvl;    /**< Level of the value last stored there. */
} LvlField;

/** One tracked binding. */
typedef struct {
    const char *cname;                        /**< Checker-assigned C name. */
    int         lvl;                          /**< Level of the whole value. */
    bool        movable;                      /**< Every definition was a movable site. */
    int         nfields;                      /**< Tracked fields, at most `LVL_MAX_FIELDS`. */
    LvlField    fields[LVL_MAX_FIELDS];       /**< Field facts. */
} LvlVar;

/** Fact table of one block: the binding rows plus an overflow marker. */
typedef struct {
    LvlVar vars[LVL_MAX_VARS];   /**< Rows; an absent row reads as `LVL_UNKNOWN`. */
    int    n;                    /**< Number of rows in use. */
    bool   overflow;             /**< More bindings than rows: every lookup gives up. */
} LvlFacts;

/** Evaluation context: the checker, the fact table, and the statement's place level. */
typedef struct {
    Checker  *c;      /**< Checker, for name resolution and the type table. */
    LvlFacts *facts;  /**< Facts at the point of the question. */
    int       place;  /**< Place level of the enclosing statement. */
} Lvl;

/** Number of lines printed so far, for the `LVL_MAX_PRINT` cap. */
static long g_lvlLines = 0;

/**
 * @brief Compare two C names, tolerating NULL.
 *
 * @param a  First name; NULL is equal only to NULL.
 * @param b  Second name.
 * @return   True when both are the same non-empty string.
 */
static bool lvlNameEq(const char *a, const char *b) {
    if (!a || !b) return a == b;
    return strcmp(a, b) == 0;
}

/**
 * @brief Find a binding's row.
 *
 * @param f      Fact table; NULL returns NULL.
 * @param cname  C name; NULL returns NULL.
 * @return       The row, or NULL when the binding is not tracked (which reads as
 *               `LVL_UNKNOWN`).
 */
static LvlVar *lvlFind(LvlFacts *f, const char *cname) {
    if (!f || !cname || f->overflow) return NULL;
    for (int i = 0; i < f->n; i++)
        if (lvlNameEq(f->vars[i].cname, cname)) return &f->vars[i];
    return NULL;
}

/**
 * @brief Find or create a binding's row.
 *
 * A full table sets `overflow`, after which every lookup gives up and every value reads
 * as `LVL_UNKNOWN`: the analysis then only ever rejects, which is the safe direction.
 *
 * @param f      Fact table; NULL returns NULL.
 * @param cname  C name; NULL returns NULL.
 * @return       The row, or NULL when the table is full.
 */
static LvlVar *lvlRow(LvlFacts *f, const char *cname) {
    if (!f || !cname || f->overflow) return NULL;
    LvlVar *v = lvlFind(f, cname);
    if (v) return v;
    if (f->n >= LVL_MAX_VARS) { f->overflow = true; return NULL; }
    v = &f->vars[f->n++];
    memset(v, 0, sizeof *v);
    v->cname = cname;
    v->lvl = LVL_NONE;
    v->movable = false;
    v->nfields = 0;
    return v;
}

/**
 * @brief Join a value into a binding's fact: take the deeper level and the weaker
 *        movability.
 *
 * @param f        Fact table.
 * @param cname    Binding's C name; NULL does nothing.
 * @param lvl      Level of the new value.
 * @param movable  Whether the new value is a movable allocation site.
 */
static void lvlRaise(LvlFacts *f, const char *cname, int lvl, bool movable) {
    if (!f || !cname || f->overflow) return;
    LvlVar *v = lvlFind(f, cname);
    if (!v) {
        /* A binding first seen through a join (a declaration inside a loop or a branch):
         * the join's bottom is the value itself, so the movability is kept. */
        v = lvlRow(f, cname);
        if (!v) return;
        v->lvl = lvl;
        v->movable = movable;
        return;
    }
    if (lvl > v->lvl) v->lvl = lvl;
    v->movable = v->movable && movable;
}

/**
 * @brief Define a binding's fact outright (a declaration, not a join).
 *
 * @param f        Fact table.
 * @param cname    Binding's C name; NULL does nothing.
 * @param lvl      Level of the initial value.
 * @param movable  Whether the initial value is a movable allocation site.
 */
static void lvlSet(LvlFacts *f, const char *cname, int lvl, bool movable) {
    LvlVar *v = lvlRow(f, cname);
    if (!v) return;
    v->lvl = lvl;
    v->movable = movable;
    v->nfields = 0;
}

/**
 * @brief Join a value into one field of a binding.
 *
 * @param f      Fact table.
 * @param cname  Binding's C name; NULL does nothing.
 * @param field  Field name; NULL does nothing.
 * @param lvl    Level of the stored value.
 */
static void lvlRaiseField(LvlFacts *f, const char *cname, const char *field, int lvl) {
    if (!field) return;
    LvlVar *v = lvlRow(f, cname);
    if (!v) return;
    for (int i = 0; i < v->nfields; i++)
        if (lvlNameEq(v->fields[i].name, field)) {
            if (lvl > v->fields[i].lvl) v->fields[i].lvl = lvl;
            return;
        }
    if (v->nfields < LVL_MAX_FIELDS) {
        v->fields[v->nfields].name = field;
        v->fields[v->nfields].lvl = lvl;
        v->nfields++;
        return;
    }
    /* A fifth field cannot be tracked, so the binding's own level carries it: the level
     * must hold for every field, and the whole value is an upper bound on each. */
    if (lvl > v->lvl) v->lvl = lvl;
}

/**
 * @brief Join a whole fact table into another, row by row.
 *
 * @param dst  Destination table, updated in place.
 * @param src  Source table; NULL does nothing.
 */
static void lvlJoinInto(LvlFacts *dst, const LvlFacts *src) {
    if (!dst || !src) return;
    for (int i = 0; i < src->n; i++) {
        const LvlVar *sv = &src->vars[i];
        lvlRaise(dst, sv->cname, sv->lvl, sv->movable);
        for (int k = 0; k < sv->nfields; k++)
            lvlRaiseField(dst, sv->cname, sv->fields[k].name, sv->fields[k].lvl);
    }
    if (src->overflow) dst->overflow = true;
}

/**
 * @brief Tell whether two fact tables are equal, row by row.
 *
 * Used as the loop fixed-point test; names are compared too, because a row inserted by a
 * different path is a change even when the numbers happen to match.
 *
 * @param a  First table.
 * @param b  Second table.
 * @return   True when every row and every field agrees.
 */
static bool lvlSame(const LvlFacts *a, const LvlFacts *b) {
    if (a->n != b->n || a->overflow != b->overflow) return false;
    for (int i = 0; i < a->n; i++) {
        const LvlVar *x = &a->vars[i];
        const LvlVar *y = &b->vars[i];
        if (!lvlNameEq(x->cname, y->cname)) return false;
        if (x->lvl != y->lvl || x->movable != y->movable) return false;
        if (x->nfields != y->nfields) return false;
        for (int k = 0; k < x->nfields; k++)
            if (x->fields[k].lvl != y->fields[k].lvl) return false;
    }
    return true;
}

/**
 * @brief Copy one fact table over another.
 *
 * @param to    Destination.
 * @param from  Source.
 */
static void lvlCopy(LvlFacts *to, const LvlFacts *from) { *to = *from; }

/**
 * @brief Allocate a zeroed fact table in the checker's arena.
 *
 * A table holds 256 rows and is too large for a recursive frame, so the tables a branch or
 * a loop needs live in the arena and are released with it.
 *
 * @param c  Checker, for the arena.
 * @return   A zeroed, empty table; never NULL.
 */
static LvlFacts *lvlFactsNew(Checker *c) {
    return (LvlFacts *)arenaAllocZero(c->arena, sizeof(LvlFacts));
}

/**
 * @brief Return the binding at the root of a place expression.
 *
 * Mirrors `dfRootOf`: the binding pinned on the node wins over a name lookup, because this
 * analysis runs after the body has been checked.
 *
 * @param c  Checker.
 * @param e  Place expression: a name, field, index, or slice.
 * @return   The root binding, or NULL when the expression is not a place.
 */
static Sym *lvlRootOf(Checker *c, Expr *e) {
    for (Expr *x = e; x; ) {
        if (x->kind == EX_IDENT) {
            Sym *sy = identBindOf(x);
            return sy ? sy : (x->u.ident.name ? lookup(c, x->u.ident.name) : NULL);
        }
        if (x->kind == EX_FIELD) { x = x->u.field.obj; continue; }
        if (x->kind == EX_INDEX) { x = x->u.index.obj; continue; }
        if (x->kind == EX_SLICE) { x = x->u.slice.obj; continue; }
        return NULL;
    }
    return NULL;
}

/**
 * @brief Tell whether a binding is a module-level one (its storage lives forever).
 *
 * @param c      Checker.
 * @param cname  Binding's C name; NULL returns false.
 * @return       True when the name belongs to a global.
 */
static bool lvlIsGlobal(Checker *c, const char *cname) {
    if (!c || !cname) return false;
    for (size_t i = 0; i < c->globals.len; i++) {
        Sym *sy = *(Sym **)vecAt(&c->globals, i);
        if (sy && lvlNameEq(sy->cname, cname)) return true;
    }
    return false;
}

/**
 * @brief Tell whether an expression's bytes can be described at all by this lattice.
 *
 * @param c  Checker, for the type table.
 * @param e  Expression; NULL returns false.
 * @return   True when the type may carry a reference, or mentions a type parameter.
 */
static bool lvlCarriesPlace(Checker *c, Expr *e) {
    if (!e || !e->type) return false;
    if (mentionsParam(e->type)) return true;
    return typeContainsRef(c->tt, tsub(c, e->type));
}

/**
 * @brief Translate a level into the words used in the debug line.
 *
 * @param lvl  Level to name.
 * @return     A static string: `none`, `unknown`, `world` for 0, or the number.
 */
static const char *lvlName(int lvl) {
    static char buf[16];
    if (lvl == LVL_NONE) return "none";
    if (lvl == LVL_UNKNOWN) return "unknown";
    if (lvl == 0) return "world";
    snprintf(buf, sizeof buf, "%d", lvl);
    return buf;
}

/**
 * @brief The store rule: does a value at this level fit into a place at that level?
 *
 * @param argLvl    Level of the value (numeric; `LVL_NONE` fits anywhere).
 * @param movable   Whether the value's site can be lowered to the destination.
 * @param placeLvl  Level of the destination place.
 * @return          True when the store is safe.
 */
static bool lvlFits(int argLvl, bool movable, int placeLvl) {
    if (argLvl == LVL_NONE) return true;
    if (movable) return true;                  /* S1: the site moves to the place */
    if (argLvl == LVL_UNKNOWN) return false;   /* top: reject at any store */
    if (placeLvl < 0) return false;            /* no usable destination */
    return argLvl <= placeLvl;                 /* level 0 (beyond the frame) fits level 0 */
}

/**
 * @brief Evaluate one expression to a level and a movability bit.
 *
 * The transfer rules are structural: a view borrows its base's place, a fresh allocation
 * site is born in the place of the statement, a call is only as good as the callee's
 * `makesPool` summary, and everything the analysis cannot name is `LVL_UNKNOWN`.
 *
 * @param a        Evaluation context.
 * @param e        Expression; NULL is `LVL_NONE`.
 * @param movable  Receives "the bytes come from a movable site"; never NULL.
 * @param hops     Recursion depth; beyond `LVL_MAX_NEST` the answer is `LVL_UNKNOWN`.
 * @return         The level.
 */
static int lvlEval(Lvl *a, Expr *e, bool *movable, int hops) {
    *movable = false;
    if (!e) return LVL_NONE;
    if (hops > LVL_MAX_NEST) return LVL_UNKNOWN;
    /*@@all-kinds*/
    switch (e->kind) {
    case EX_INT:
    case EX_FLOAT:
    case EX_BOOL:
    case EX_STR:
    case EX_NULL:
        /* A literal owns no place bytes (a string literal points into read-only data,
         * which lives forever), so it fits in every place. */
        return LVL_NONE;
    case EX_IDENT: {
        Sym *sy = identBindOf(e);
        if (!sy && e->u.ident.name) sy = lookup(a->c, e->u.ident.name);
        if (!sy || !sy->cname) return LVL_UNKNOWN;
        if (lvlIsGlobal(a->c, sy->cname)) return 0;   /* the storage outlives the frame */
        LvlVar *v = lvlFind(a->facts, sy->cname);
        if (!v) return LVL_UNKNOWN;   /* a parameter, or a binding the walk did not reach */
        *movable = v->movable;
        return v->lvl;
    }
    case EX_FIELD: {
        Sym *root = lvlRootOf(a->c, e);
        if (root && root->cname) {
            LvlVar *v = lvlFind(a->facts, root->cname);
            if (v)
                for (int i = 0; i < v->nfields; i++)
                    if (lvlNameEq(v->fields[i].name, e->u.field.name))
                        return v->fields[i].lvl;
        }
        /* Not tracked: the base's own level is the conservative answer. A field view is
         * not movable: it borrows the base, it is not the base's allocation site. */
        bool mv = false;
        int lv = lvlEval(a, e->u.field.obj, &mv, hops + 1);
        return lv;
    }
    case EX_INDEX: {
        bool mv = false;
        return lvlEval(a, e->u.index.obj, &mv, hops + 1);
    }
    case EX_SLICE: {
        bool mv = false;
        return lvlEval(a, e->u.slice.obj, &mv, hops + 1);
    }
    case EX_REF: {
        bool mv = false;
        return lvlEval(a, e->u.ref.operand, &mv, hops + 1);
    }
    case EX_DEREF: {
        bool mv = false;
        return lvlEval(a, e->u.deref.operand, &mv, hops + 1);
    }
    case EX_SIGN: {
        bool mv = false;
        return lvlEval(a, e->u.sign.operand, &mv, hops + 1);
    }
    case EX_CONV: {
        bool mv = false;
        int lv = lvlEval(a, e->u.conv.operand, &mv, hops + 1);
        *movable = mv && lv != LVL_UNKNOWN;
        return lv;
    }
    case EX_TRY:
        /* The error path leaves the value unset; nothing is known about it. */
        return LVL_UNKNOWN;
    case EX_EXT:
        /* A spawned call's result belongs to the callee's frame. */
        return LVL_UNKNOWN;
    case EX_COALESCE: {
        bool m1 = false, m2 = false;
        int l1 = lvlEval(a, e->u.coalesce.main, &m1, hops + 1);
        int l2 = lvlEval(a, e->u.coalesce.fallback, &m2, hops + 1);
        *movable = m1 && m2;
        return l1 > l2 ? l1 : l2;
    }
    case EX_BIN:
    case EX_UN: {
        /* An operator resolved to a method is a call; a builtin operator only computes a
         * scalar. */
        if (planCallee(e)) {
            FuncDef *cal = planCallee(e);
            if (calleeMakesPool(cal)) {
                *movable = true;
                return a->place;
            }
            return LVL_UNKNOWN;
        }
        *movable = false;
        if (lvlCarriesPlace(a->c, e)) return LVL_UNKNOWN;
        return LVL_NONE;
    }
    case EX_NEW: {
        /* A fresh allocation in the place of the statement. `anLexicalLevel` is the block
         * the site was born in, recorded before the plan rewrote the arena level; a site
         * without one falls back to the statement's place. */
        int lv = anLexicalLevel(e);
        if (lv <= 0) lv = a->place;
        *movable = true;
        return lv;
    }
    case EX_GENCALL: {
        const char *nm = e->u.gencall.name;
        /* The pool primitives hand out a slice of the pool's own plate: a borrow, not an
         * allocation. Everything else (`alloc<T>(n)`) is a fresh arena block. */
        if (nm && (strcmp(nm, "poolSlice") == 0 || strcmp(nm, "poolSliceRaw") == 0 ||
                   strcmp(nm, "poolResize") == 0 || strcmp(nm, "poolResizeRaw") == 0 ||
                   strcmp(nm, "poolGive") == 0 || strcmp(nm, "copyInto") == 0))
            return LVL_UNKNOWN;
        int lv = anLexicalLevel(e);
        if (lv <= 0) lv = a->place;
        *movable = true;
        return lv;
    }
    case EX_STRUCTLIT: {
        /* A fresh aggregate site: the literal itself can be lowered, and a field that
         * carries no place bytes never stands in the way. A field that does carry bytes
         * keeps the site honest only when that value can be lowered too. */
        int lv = a->place;
        bool mv = true;
        for (size_t i = 0; i < e->u.lit.inits.len; i++) {
            FieldInit *fi = *(FieldInit **)vecAt(&e->u.lit.inits, i);
            bool m = false;
            int x = lvlEval(a, fi->value, &m, hops + 1);
            if (x > lv) lv = x;
            if (x != LVL_NONE && !m) mv = false;
        }
        *movable = mv;
        return lv;
    }
    case EX_LAMBDA: {
        /* The value is the capture environment, so the captures are exactly the fields of
         * a struct literal born in this place. */
        int lv = a->place;
        bool mv = true;
        for (size_t i = 0; i < e->u.lambda.inits.len; i++) {
            FieldInit *fi = *(FieldInit **)vecAt(&e->u.lambda.inits, i);
            bool m = false;
            int x = lvlEval(a, fi->value, &m, hops + 1);
            if (x > lv) lv = x;
            if (x != LVL_NONE && !m) mv = false;
        }
        *movable = mv;
        return lv;
    }
    case EX_ARRAYLIT: {
        int lv = a->place;
        bool mv = true;
        for (size_t i = 0; i < e->u.arraylit.elems.len; i++) {
            bool m = false;
            int x = lvlEval(a, *(Expr **)vecAt(&e->u.arraylit.elems, i), &m, hops + 1);
            if (x > lv) lv = x;
            if (x != LVL_NONE && !m) mv = false;
        }
        *movable = mv;
        return lv;
    }
    case EX_ENUMVAL: {
        int lv = a->place;
        bool mv = true;
        for (size_t i = 0; i < e->u.enumval.args.len; i++) {
            bool m = false;
            int x = lvlEval(a, *(Expr **)vecAt(&e->u.enumval.args, i), &m, hops + 1);
            if (x > lv) lv = x;
            if (x != LVL_NONE && !m) mv = false;
        }
        *movable = mv;
        return lv;
    }
    case EX_DYN: {
        /* The box is born here; the payload is copied into it, so its references travel
         * with it and can only be moved if the payload itself is movable. */
        bool m = false;
        int x = lvlEval(a, e->u.dynv.payload, &m, hops + 1);
        *movable = m;
        if (x < a->place) x = a->place;
        return x;
    }
    case EX_CALL:
    case EX_ASSOC:
    case EX_METHOD: {
        Vec *args = e->kind == EX_CALL ? &e->u.call.args
                  : e->kind == EX_ASSOC ? &e->u.assoc.args : &e->u.method.args;
        FuncDef *cal = planCallee(e);
        int lv = LVL_UNKNOWN;
        bool mv = false;
        if (cal && calleeMakesPool(cal)) {
            lv = a->place;
            mv = true;
        } else {
            /* A call that does not build a pool still has a result whose bytes may
             * borrow from the receiver or the arguments: a container read
             * (`k.atDense(0)`), an `at` on a slice, a view returned by a getter. When the
             * result is a view or a reference, its level is the deepest of those; any
             * other result stays unknown. The maximum only ever raises the level, so this
             * refinement can never accept a store the conservative answer rejects. */
            Type *rt = e->type ? tsub(a->c, e->type) : NULL;
            if (rt && !mentionsParam(rt) &&
                (rt->kind == TY_REF || ttIsViewType(ttBase(rt)))) {
                int best = LVL_NONE;
                bool any = false;
                if (e->kind == EX_METHOD) {
                    bool m = false;
                    int x = lvlEval(a, e->u.method.recv, &m, hops + 1);
                    if (x > best) best = x;
                    any = true;
                }
                for (size_t i = 0; i < args->len; i++) {
                    bool m = false;
                    int x = lvlEval(a, *(Expr **)vecAt(args, i), &m, hops + 1);
                    if (x > best) best = x;
                    any = true;
                }
                if (any) lv = best;
            }
        }
        *movable = mv;
        return lv;
    }
    default:
        break;
    }
    return LVL_UNKNOWN;
}

/**
 * @brief Evaluate an expression to a level.
 *
 * @param a  Evaluation context.
 * @param e  Expression.
 * @return   The level.
 */
static int lvlOfExpr(Lvl *a, Expr *e) {
    bool mv = false;
    return lvlEval(a, e, &mv, 0);
}

/** @brief Walk a block's statements in order. */
static void lvlBlockStmt(Checker *c, Stmt *block, LvlFacts *f, int lvl);

/**
 * @brief Apply one statement's transfer rule to the fact table.
 *
 * Follows the structured tree: sequential statements chain, both arms of an `if` are
 * walked from the same input and joined, and a loop body is iterated until the facts stop
 * changing. The nesting parameter is the block's place level, which is also the level of a
 * fresh allocation made in the statement.
 *
 * @param c    Checker.
 * @param s    Statement; NULL does nothing.
 * @param f    Fact table, updated in place.
 * @param lvl  Place level of statements in this block (the body is 1).
 */
static void lvlStmt(Checker *c, Stmt *s, LvlFacts *f, int lvl) {
    if (!s) return;
    if (lvl > LVL_MAX_NEST) { f->overflow = true; return; }
    Lvl a = { c, f, lvl };
    /*@@all-kinds*/
    switch (s->kind) {
    case ST_VAR: {
        const char *cn = planCName(s);
        if (!cn) break;
        if (!s->u.var.init) {
            /* Declared without an initializer: its storage is unset until a store, and a
             * store can only be seen by the assignment rule below. */
            lvlSet(f, cn, LVL_UNKNOWN, false);
            break;
        }
        if (s->u.var.init->kind == EX_STRUCTLIT) {
            /* The literal is a fresh site in this place, so the site (and therefore the
             * binding) can be lowered to a shallower destination. */
            lvlSet(f, cn, lvl, true);
            for (size_t i = 0; i < s->u.var.init->u.lit.inits.len; i++) {
                FieldInit *fi = *(FieldInit **)vecAt(&s->u.var.init->u.lit.inits, i);
                lvlRaiseField(f, cn, fi->name, lvlOfExpr(&a, fi->value));
            }
            break;
        }
        if (!lvlCarriesPlace(c, s->u.var.init)) { lvlSet(f, cn, LVL_NONE, false); break; }
        bool mv = false;
        int x = lvlEval(&a, s->u.var.init, &mv, 0);
        lvlSet(f, cn, x, mv);
        break;
    }
    case ST_ASSIGN: {
        Sym *root = lvlRootOf(c, s->u.assign.target);
        if (!root || !root->cname) break;
        bool mv = false;
        int x = lvlEval(&a, s->u.assign.value, &mv, 0);
        ExprKind tk = s->u.assign.target->kind;
        if (tk == EX_FIELD) {
            lvlRaiseField(f, root->cname, s->u.assign.target->u.field.name, x);
        } else if (tk == EX_INDEX || tk == EX_SLICE || tk == EX_DEREF) {
            /* An element store does not replace the binding: it can only make the bytes
             * behind the binding look deeper when the stored value itself carries a place.
             * An `i64` into `p[0]` leaves the fact, and the binding's movability, alone. */
            if (x != LVL_NONE) lvlRaise(f, root->cname, x, false);
        } else {
            lvlRaise(f, root->cname, x, mv);
            Sym *src = lvlRootOf(c, s->u.assign.value);
            if (src && src->cname) {
                LvlVar *sv = lvlFind(f, src->cname);
                if (sv)
                    for (int i = 0; i < sv->nfields; i++)
                        lvlRaiseField(f, root->cname, sv->fields[i].name, sv->fields[i].lvl);
            }
        }
        break;
    }
    case ST_IF: {
        LvlFacts *thenF = lvlFactsNew(c);
        LvlFacts *elseF = lvlFactsNew(c);
        lvlCopy(thenF, f);
        lvlCopy(elseF, f);
        lvlBlockStmt(c, s->u.ifs.thenBody, thenF, lvl + 1);
        if (s->u.ifs.elseBody) lvlBlockStmt(c, s->u.ifs.elseBody, elseF, lvl + 1);
        lvlJoinInto(f, thenF);
        lvlJoinInto(f, elseF);
        break;
    }
    case ST_WHILE: {
        LvlFacts *saved = lvlFactsNew(c);
        LvlFacts *body = lvlFactsNew(c);
        int rounds = 0;
        for (;;) {
            lvlCopy(saved, f);
            lvlCopy(body, f);
            lvlBlockStmt(c, s->u.whiles.body, body, lvl + 1);
            lvlJoinInto(f, body);
            rounds++;
            if (lvlSame(saved, f)) break;
            if (rounds >= LVL_ROUNDS) { f->overflow = true; break; }
        }
        break;
    }
    case ST_BLOCK:
        lvlBlockStmt(c, s, f, lvl);
        break;
    case ST_MATCH: {
        LvlFacts *acc = lvlFactsNew(c);
        LvlFacts *arm = lvlFactsNew(c);
        lvlCopy(acc, f);
        for (size_t i = 0; i < s->u.match.arms.len; i++) {
            MatchArm *m = *(MatchArm **)vecAt(&s->u.match.arms, i);
            int sd = lvlOfExpr(&a, s->u.match.scrutinee);
            for (size_t k = 0; k < m->binds.len; k++) {
                const char *bn = *(const char **)vecAt(&m->binds, k);
                if (bn) lvlRaise(f, bn, sd, false);
            }
            lvlCopy(arm, f);
            lvlBlockStmt(c, m->body, arm, lvl + 1);
            lvlJoinInto(acc, arm);
        }
        lvlJoinInto(f, acc);
        break;
    }
    case ST_DOMAIN:
        lvlBlockStmt(c, s->u.domain_.body, f, lvl + 1);
        break;
    case ST_RETURN:
    case ST_BREAK:
    case ST_CONTINUE:
    case ST_EXPR:
    case ST_YIELD:
    case ST_TRAP:
    case ST_DROP:
        break;
    }
}

/**
 * @brief Walk a block's statements in order.
 *
 * @param c      Checker.
 * @param block  Block to walk; a non-block degrades to a single statement.
 * @param f      Fact table, updated in place.
 * @param lvl    Place level of statements in this block.
 */
static void lvlBlockStmt(Checker *c, Stmt *block, LvlFacts *f, int lvl) {
    if (!block) return;
    if (block->kind != ST_BLOCK) { lvlStmt(c, block, f, lvl); return; }
    for (size_t i = 0; i < block->u.block.stmts.len; i++)
        lvlStmt(c, *(Stmt **)vecAt(&block->u.block.stmts, i), f, lvl);
}

/**
 * @brief Short name of an expression kind, for the debug line.
 *
 * @param k  Expression kind.
 * @return   A static name such as `ident`, `slice`, or `call`.
 */
static const char *lvlKindName(ExprKind k) {
    switch (k) {
    case EX_INT: return "int";
    case EX_FLOAT: return "float";
    case EX_BOOL: return "bool";
    case EX_STR: return "str";
    case EX_IDENT: return "ident";
    case EX_BIN: return "bin";
    case EX_UN: return "un";
    case EX_CALL: return "call";
    case EX_METHOD: return "method";
    case EX_FIELD: return "field";
    case EX_STRUCTLIT: return "structlit";
    case EX_INDEX: return "index";
    case EX_SLICE: return "slice";
    case EX_ARRAYLIT: return "arraylit";
    case EX_REF: return "ref";
    case EX_ASSOC: return "assoc";
    case EX_GENCALL: return "gencall";
    case EX_TRY: return "try";
    case EX_DEREF: return "deref";
    case EX_ENUMVAL: return "enumval";
    case EX_CONV: return "conv";
    case EX_NEW: return "new";
    case EX_COALESCE: return "coalesce";
    case EX_SIGN: return "sign";
    case EX_NULL: return "null";
    case EX_DYN: return "dyn";
    case EX_EXT: return "ext";
    case EX_LAMBDA: return "lambda";
    }
    return "expr";
}

/**
 * @brief Strongest decision any pass recorded for one argument of one call.
 *
 * The same call is checked more than once while the effects of its callee settle (an
 * earlier pass may only know "the callee may store"), and the diagnostic a later pass
 * emits is the one that stands. Ranking the passes and keeping the strongest answer makes
 * the report speak for the run as a whole instead of for one intermediate pass.
 *
 * @param c  Checker, holding every recorded site.
 * @param s  Site the argument belongs to.
 * @param j  Argument index.
 * @return   The strongest `LVL_CAND_*` code recorded for that line, callee, and index.
 */
static unsigned char lvlBestDecision(Checker *c, LvlSite *s, int j) {
    unsigned char best = s->decision[j];
    for (size_t i = 0; i < c->lvlSites.len; i++) {
        LvlSite *o = *(LvlSite **)vecAt(&c->lvlSites, i);
        if (!o || o == s || o->fn != s->fn || o->line != s->line) continue;
        if (o->nargs != s->nargs) continue;
        if (!lvlNameEq(o->fname, s->fname)) continue;
        if (o->decision[j] > best) best = o->decision[j];
    }
    return best;
}

/**
 * @brief Whether an earlier recorded site already covers this argument.
 *
 * One call is checked once per pass, and a pass that runs after the callee's effects
 * settled sees exactly the same arguments again. The report wants one line per argument,
 * so only the first recorded site for `(body, line, callee, index)` prints.
 *
 * @param c    Checker, holding every recorded site.
 * @param self Index of the site being reported in `c->lvlSites`.
 * @param s    Site being reported.
 * @param j    Argument index.
 * @return     True when a site recorded earlier already covers this argument.
 */
static bool lvlSeenBefore(Checker *c, size_t self, LvlSite *s, int j) {
    for (size_t i = 0; i < self && i < c->lvlSites.len; i++) {
        LvlSite *o = *(LvlSite **)vecAt(&c->lvlSites, i);
        if (!o || o->fn != s->fn || o->line != s->line) continue;
        if (o->nargs != s->nargs || !lvlNameEq(o->fname, s->fname)) continue;
        if (o->decision[j] != LVL_CAND_NONE) return true;
    }
    return false;
}

/**
 * @brief Report one recorded call site's arguments against the store rule.
 *
 * Only disagreements are printed: an accepted argument the analysis would reject (the
 * unsound direction), a rejected argument the analysis would accept (the over-strict
 * direction), and an argument the checker never judged at all but the analysis rejects.
 *
 * @param c      Checker.
 * @param facts  Facts at the fixed point of the whole body.
 * @param s      Recorded call site.
 */
static void lvlReportSite(Checker *c, LvlFacts *facts, LvlSite *s, size_t self) {
    for (int j = 0; j < s->nargs; j++) {
        unsigned char cur = lvlBestDecision(c, s, j);
        if (cur == LVL_CAND_NONE) continue;
        if (lvlSeenBefore(c, self, s, j)) continue;
        Lvl a = { c, facts, s->place };
        bool mv = false;
        int al = lvlEval(&a, s->args[j], &mv, 0);
        bool ok = lvlFits(al, mv, s->h);
        const char *env = getenv("EXTC_DBG_LVL");
        bool dumpAll = env && env[0] == '2';
        if (!dumpAll) {
            if (cur == LVL_CAND_ACCEPT && ok) continue;
            if (cur == LVL_CAND_REJECT && !ok) continue;
            if (cur == LVL_CAND_SKIP && ok) continue;
        }
        g_lvlLines++;
        if (g_lvlLines > LVL_MAX_PRINT) {
            if (g_lvlLines == LVL_MAX_PRINT + 1)
                fprintf(stderr, "[lvl] truncated at %d lines\n", LVL_MAX_PRINT);
            return;
        }
        const char *curName = cur == LVL_CAND_ACCEPT ? "accepted"
                            : cur == LVL_CAND_REJECT ? "reject" : "unchecked";
        const char *role = s->role && s->role[j] == LVL_ROLE_DEST ? "dest" : "value";
        fprintf(stderr,
                "[lvl] file=%s:%d store arg=%d callee=%s kind=%s role=%s argLvl=%s"
                " placeLvl=%d movable=%d current=%s suggested=%s\n",
                c->ctx && c->ctx->path ? c->ctx->path : "?", s->line, j + 1,
                s->fname ? s->fname : "?", lvlKindName(s->args[j]->kind), role,
                lvlName(al), s->h, mv ? 1 : 0, curName, ok ? "accept" : "reject");
    }
}

/**
 * @brief Record a call site whose arguments the callee may store.
 *
 * Returns NULL when the analysis is off, so the callers in `checkCallRefArgs` cost one
 * predictable branch and nothing else in a normal run.
 *
 * @param c      Checker.
 * @param args   Argument vector, in parameter order.
 * @param h      Place level the callee may store into.
 * @param line   Source line of the call.
 * @param fname  Callee name, for the report.
 * @return       The recorded site, or NULL when the analysis is off.
 */
LvlSite *lvlSiteNew(Checker *c, Vec *args, int h, int line, const char *fname) {
    if (!c || !c->lvlOn || !args) return NULL;
    LvlSite *s = (LvlSite *)arenaAllocZero(c->arena, sizeof(LvlSite));
    s->nargs = (int)args->len;
    s->args = (Expr **)arenaAllocZero(c->arena, sizeof(Expr *) * (size_t)(s->nargs ? s->nargs : 1));
    for (int i = 0; i < s->nargs; i++) s->args[i] = *(Expr **)vecAt(args, (size_t)i);
    s->decision = (unsigned char *)arenaAllocZero(c->arena, (size_t)(s->nargs ? s->nargs : 1));
    s->role = (unsigned char *)arenaAllocZero(c->arena, (size_t)(s->nargs ? s->nargs : 1));
    for (int i = 0; i < s->nargs; i++) s->role[i] = LVL_ROLE_UNSET;
    s->h = h;
    s->line = line;
    s->fname = fname;
    s->place = (int)c->scopes.len;
    s->fn = c->curFunc;
    *(LvlSite **)vecPush(&c->lvlSites) = s;
    return s;
}

/**
 * @brief Record what the existing checker decided about one argument.
 *
 * The codes are ranked (`none < skip < accept < reject`), so the strongest answer wins
 * when several rules look at the same argument: a rejection is never overwritten by an
 * acceptance, which mirrors the fact that an emitted diagnostic is final.
 *
 * @param s     Site; NULL does nothing.
 * @param j     Argument index.
 * @param what  Decision code.
 */
void lvlSiteMark(LvlSite *s, size_t j, unsigned char what) {
    if (!s || j >= (size_t)s->nargs) return;
    unsigned char cur = s->decision[j];
    if (what > cur) s->decision[j] = what;
}

/**
 * @brief Record what an argument's expression is: a value being stored, or a destination.
 *
 * @param s     Site; NULL does nothing.
 * @param j     Argument index.
 * @param role  `LVL_ROLE_VALUE` or `LVL_ROLE_DEST`.
 */
void lvlSiteRole(LvlSite *s, size_t j, unsigned char role) {
    if (!s || !s->role || j >= (size_t)s->nargs) return;
    if (s->role[j] == LVL_ROLE_UNSET) s->role[j] = role;   /* the first, most specific role wins */
}

/**
 * @brief Run the place-level analysis over one function body.
 *
 * Verification only: returns at once unless `EXTC_DBG_LVL` is set, and never writes a
 * diagnostic or a plan bit.
 *
 * @param c  Checker.
 * @param f  Function whose body has just been checked.
 */
void lvlAnalyze(Checker *c, FuncDef *f) {
    if (!c || !f || !f->body) return;
    if (!c->lvlOn) return;
    LvlFacts *facts = lvlFactsNew(c);
    lvlBlockStmt(c, f->body, facts, 1);
    for (size_t i = 0; i < c->lvlSites.len; i++) {
        LvlSite *s = *(LvlSite **)vecAt(&c->lvlSites, i);
        if (!s || s->fn != f) continue;
        lvlReportSite(c, facts, s, i);
    }
}
